insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Proceder à obtenção de prova, em procedimento de investigação ou fiscalização, por meio manifestamente ilícito. Pena: detenção de 1 a 4 anos e multa. Incorre na mesma pena quem faz uso de prova, em desfavor do investigado ou fiscalizado, com prévio conhecimento de sua ilicitude.', '["Obter prova por meio MANIFESTAMENTE ilícito.","Usar, contra o investigado, prova sabidamente ilícita.","Detenção de 1 a 4 anos e multa."]'::jsonb, '["A ilicitude deve ser manifesta e conhecida."]'::jsonb, 'Policial que obtém confissão sob tortura e a usa no processo comete o crime.', '["Assertiva que pune o uso de prova ilícita ainda que o agente a desconhecesse erra: exige prévio conhecimento da ilicitude."]'::jsonb, '[]'::jsonb, '["Provas ilícitas (CPP)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Requisitar instauração ou instaurar procedimento investigatório de infração penal ou administrativa, em desfavor de alguém, à falta de qualquer indício da prática de crime, de ilícito funcional ou de infração administrativa. Pena: detenção de 6 meses a 2 anos e multa. Não há crime quando se tratar de sindicância ou investigação preliminar sumária, devidamente justificada. O texto remete a ADIs no STF.', '["Requisitar ou instaurar investigação sem QUALQUER indício.","Detenção de 6 meses a 2 anos e multa.","Exclusão: sindicância ou investigação preliminar sumária justificada."]'::jsonb, '["Exige a falta de QUALQUER indício.","Há ações diretas de inconstitucionalidade (ADIs) sobre dispositivos da lei."]'::jsonb, 'Instaurar inquérito contra alguém sem qualquer indício, apenas por perseguição, é crime.', '["Assertiva que pune a instauração de sindicância preliminar justificada erra."]'::jsonb, '[]'::jsonb, '["Art. 30"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-27'
