insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Prestar informação falsa sobre procedimento judicial, policial, fiscal ou administrativo com o fim de prejudicar interesse de investigado. Pena: detenção de 6 meses a 2 anos e multa. O texto remete a ADIs no STF.', '["Prestar informação falsa sobre procedimento judicial, policial, fiscal ou administrativo.","Fim de prejudicar interesse do investigado.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["Dolo específico de prejudicar o investigado."]'::jsonb, 'Funcionário que informa falsamente a situação de um procedimento para prejudicar o investigado comete o crime.', '["Assertiva que dispensa o fim de prejudicar o investigado no art. 29 erra."]'::jsonb, '[]'::jsonb, '["Art. 1º, §1º"]'::jsonb, 'under_review', 'claude'
