insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Dar início ou proceder à persecução penal, civil ou administrativa sem justa causa fundamentada ou contra quem sabe inocente. Pena: detenção de 1 a 4 anos e multa.', '["Iniciar ou proceder à persecução sem justa causa fundamentada.","Ou contra quem se sabe inocente.","Detenção de 1 a 4 anos e multa."]'::jsonb, '["Alcança a persecução penal, civil e administrativa."]'::jsonb, 'Promotor que denuncia alguém sabendo-o inocente comete o crime.', '["Assertiva que restringe o art. 30 à persecução penal erra: abrange a civil e a administrativa."]'::jsonb, '[]'::jsonb, '["Art. 27"]'::jsonb, 'under_review', 'claude'
