insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Estender injustificadamente a investigação, procrastinando-a em prejuízo do investigado ou fiscalizado. Pena: detenção de 6 meses a 2 anos e multa. Incorre na mesma pena quem, inexistindo prazo para execução ou conclusão de procedimento, o estende de forma imotivada, procrastinando-o em prejuízo do investigado ou do fiscalizado. O texto remete a ADIs no STF.', '["Estender injustificadamente a investigação em prejuízo do investigado.","Inclusive quando não há prazo legal, de forma imotivada.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["Alcança procedimentos sem prazo legal."]'::jsonb, 'Deixar um inquérito aberto por anos, sem diligências, para prejudicar o investigado, é crime.', '["Assertiva que isenta a extensão da investigação quando não há prazo legal erra."]'::jsonb, '[]'::jsonb, '["Art. 10 do CPP"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-31'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Negar ao interessado, seu defensor ou advogado acesso aos autos de investigação preliminar, ao termo circunstanciado, ao inquérito ou a qualquer outro procedimento investigatório de infração penal, civil ou administrativa, assim como impedir a obtenção de cópias, ressalvado o acesso a peças relativas a diligências em curso, ou que indiquem a realização de diligências futuras, cujo sigilo seja imprescindível. Pena: detenção de 6 meses a 2 anos e multa.', '["Negar acesso aos autos ao interessado, defensor ou advogado.","Também impedir a obtenção de cópias.","Ressalva: diligências em curso ou futuras de sigilo imprescindível.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["Relaciona-se à Súmula Vinculante 14 do STF (acesso às provas já documentadas)."]'::jsonb, 'Negar ao advogado acesso ao inquérito, fora do sigilo de diligências em curso, configura o crime.', '["Assertiva que permite negar o acesso a todas as peças do inquérito, inclusive as já documentadas, erra."]'::jsonb, '[]'::jsonb, '["Art. 20"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-32'
