insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Exigir informação ou cumprimento de obrigação, inclusive o dever de fazer ou de não fazer, sem expresso amparo legal. Pena: detenção de 6 meses a 2 anos e multa. Incorre na mesma pena quem se utiliza de cargo ou função pública ou invoca a condição de agente público para se eximir de obrigação legal ou para obter vantagem ou privilégio indevido.', '["Exigir informação ou obrigação sem expresso amparo legal.","Usar o cargo ou invocar a condição de agente público para se eximir de obrigação ou obter vantagem indevida.","Detenção de 6 meses a 2 anos e multa."]'::jsonb, '["Conhecido como ''carteirada'' no parágrafo único."]'::jsonb, 'Agente público que invoca o cargo para não pagar uma multa devida comete o crime.', '["Assertiva que isenta o agente que invoca o cargo para obter vantagem indevida erra."]'::jsonb, '[{"termo":"Carteirada","significado":"Uso do cargo para obter vantagem ou eximir-se de obrigação."}]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-33'
