insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Decretar, em processo judicial, a indisponibilidade de ativos financeiros em quantia que extrapole exacerbadamente o valor estimado para a satisfação da dívida da parte e, ante a demonstração, pela parte, da excessividade da medida, deixar de corrigi-la. Pena: detenção de 1 a 4 anos e multa.', '["Indisponibilidade de ativos que extrapole exacerbadamente a dívida.","Deixar de corrigir após demonstrada a excessividade.","Detenção de 1 a 4 anos e multa."]'::jsonb, '["Exige a omissão em CORRIGIR depois da demonstração pela parte."]'::jsonb, 'Juiz bloqueia valor muito superior à dívida e se recusa a corrigir mesmo demonstrado o excesso.', '["Assertiva que pune o bloqueio em valor superior à dívida independentemente de omissão em corrigir erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
