insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 2º da Lei da Prisão Temporária passa a vigorar com acréscimos: o mandado de prisão conterá necessariamente o período de duração da prisão temporária e o dia em que o preso deverá ser libertado; decorrido o prazo do mandado, a autoridade responsável pela custódia deverá, independentemente de nova ordem judicial, pôr imediatamente o preso em liberdade, salvo se já comunicada da prorrogação ou da decretação da prisão preventiva; e inclui-se o dia do cumprimento do mandado no cômputo do prazo da prisão temporária.', '["Mandado de prisão temporária indica a duração e o dia da soltura.","Esgotado o prazo, o preso é solto sem nova ordem judicial.","O dia do cumprimento do mandado entra no cômputo do prazo."]'::jsonb, '["Soltura automática no fim do prazo, salvo prorrogação ou preventiva."]'::jsonb, 'Terminado o prazo da prisão temporária, o preso é solto imediatamente, sem nova ordem.', '["Assertiva que exige nova ordem judicial para soltar o preso temporário ao fim do prazo erra."]'::jsonb, '[]'::jsonb, '["Art. 12, parágrafo único, IV"]'::jsonb, 'under_review', 'claude'
