insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 10 da Lei de Interceptação Telefônica passa a vigorar com nova redação: constitui crime realizar interceptação de comunicações telefônicas, de informática ou telemática, promover escuta ambiental ou quebrar segredo da Justiça, sem autorização judicial ou com objetivos não autorizados em lei. Pena: reclusão de 2 a 4 anos e multa. Incorre na mesma pena a autoridade judicial que determina a execução de conduta prevista no caput com objetivo não autorizado em lei.', '["Crime: interceptação, escuta ambiental ou quebra de segredo de Justiça sem autorização judicial ou fora das hipóteses legais.","Reclusão de 2 a 4 anos e multa.","Mesma pena para o juiz que determina conduta com objetivo não autorizado."]'::jsonb, '["Alteração da Lei da Interceptação, não da Lei de Abuso."]'::jsonb, 'Grampo telefônico sem autorização judicial configura o crime do art. 10 da Lei de Interceptação.', '["Assertiva que isenta o magistrado que determina interceptação para fim não autorizado erra."]'::jsonb, '[]'::jsonb, '["Lei de Interceptação Telefônica"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-41'
