insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Estatuto da Criança e do Adolescente passa a vigorar acrescido do art. 227-A: os efeitos da condenação do inciso I do art. 92 do Código Penal, para os crimes da Lei de Abuso de Autoridade praticados por servidores públicos com abuso de autoridade, são condicionados à ocorrência de reincidência. A perda do cargo, do mandato ou da função, nesse caso, independerá da pena aplicada na reincidência.', '["Acréscimo ao ECA (art. 227-A).","Perda do cargo como efeito da condenação depende de reincidência.","Perda do cargo independe da pena aplicada na reincidência."]'::jsonb, '["Harmoniza o efeito da condenação com o art. 4º."]'::jsonb, 'A perda do cargo só ocorre se o servidor for reincidente no crime de abuso de autoridade.', '["Assertiva que torna a perda do cargo efeito automático da primeira condenação erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'abuso' and u.unit_key = 'art-42'
